const raw = $input.first()?.json?.output ?? '';
const topic = $('Benchmark Topic Input').first().json.chatInput;
let parsed;
try {
  let cleaned = String(raw).trim();
  if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { provider: 'tavily', sources: [], parseError: String(e) };
}
const valid = Array.isArray(parsed.sources) ? parsed.sources.filter(s => {
  if (!s || typeof s.title !== 'string' || !s.title.trim() || typeof s.url !== 'string' || typeof s.snippet !== 'string' || s.snippet.trim().length < 35) return false;
  try { const u = new URL(s.url); return u.protocol === 'https:' || u.protocol === 'http:'; } catch { return false; }
}) : [];
const unique = [...new Map(valid.map(s => [s.url, s])).values()];
return [{ json: { topic, provider: 'tavily', researchData: unique, sourceCount: unique.length, researchValid: unique.length >= 3, validationReason: unique.length >= 3 ? 'Tavily returned at least three usable records' : 'Fewer than three usable Tavily records or invalid JSON' } }];

const data = $input.first()?.json ?? {};
const rawOrganic = data.organic;
const organic = Array.isArray(rawOrganic) ? rawOrganic : (rawOrganic && typeof rawOrganic === 'object' ? Object.values(rawOrganic) : []);
const sources = organic.filter(s => {
  if (!s || typeof s.title !== 'string' || !s.title.trim() || typeof s.link !== 'string' || typeof (s.snippet || s.description) !== 'string' || String(s.snippet || s.description).trim().length < 25) return false;
  const url = s.link.trim();
  return (url.startsWith('https://') || url.startsWith('http://')) && !url.includes('google.com/goto');
}).map(s => ({ title: s.title, url: s.link, snippet: s.snippet || s.description, sourceType: 'search-result' }));
const unique = [...new Map(sources.map(s => [s.url,s])).values()];
return [{ json: { topic: $('Benchmark Topic Input').first().json.chatInput, provider: 'bright_data_fallback', researchData: unique, sourceCount: unique.length, organicCount: organic.length, researchValid: unique.length >= 2, validationReason: unique.length >= 2 ? 'Bright Data returned at least two direct usable organic results; evidence scope remains limited' : 'Fewer than two usable Bright Data organic results' } }];

const j = $input.first()?.json ?? {};
const raw = j.output;
const ok = typeof raw === 'string' && raw.trim().length > 20;
return [{ json: { ...j, useNvidiaFallback: !ok } }];

const j = $input.first()?.json ?? {};
const raw = j.output;
const ok = typeof raw === 'string' && raw.trim().length > 100;
return [{ json: { ...j, useNvidiaFallback: !ok } }];

const j = $input.first()?.json ?? {};
if (!j.researchValid || !Array.isArray(j.researchData) || j.researchData.length < 2) throw new Error('Validated research pack missing or insufficient; writer must not run.');
return [{ json: { topic: j.topic, provider: j.provider, researchData: j.researchData, sourceCount: j.researchData.length, evidenceScope: j.validationReason || '' } }];
